"""Exact item tables exported from the user-supplied sIO module 37013.c.

The JSON is zlib-compressed only to keep the generated source file compact and
to avoid hand-edited JSON corruption.
"""
from __future__ import annotations

import base64
import json
import zlib

_COMPRESSED = ""
SIO_ITEMS = json.loads(zlib.decompress(base64.b64decode(_COMPRESSED)).decode("utf-8"))
